static const simge_t SIMGELER[SIMGE_SAYI] = {
    { "Klasor", "Bilgiyi saklar", s32_KLASOR, s48_KLASOR, s64_KLASOR, p_KLASOR },
    { "Sabit Disk", "Koklerimiz kadar derin", s32_DISK, s48_DISK, s64_DISK, p_DISK },
    { "Cop Kutusu", "Gereksizi birak", s32_COP, s48_COP, s64_COP, p_COP },
};

const simge_t *simge_al(simge_id_t id) {
    return (id >= 0 && id < SIMGE_SAYI) ? &SIMGELER[id] : 0;
}

static uint32_t harman(uint32_t zem, uint32_t on, int a) {
    if (a >= 15) return on;
    if (a <= 0)  return zem;
    int zr=(int)((zem>>16)&0xFF), zg=(int)((zem>>8)&0xFF), zb=(int)(zem&0xFF);
    int orr=(int)((on>>16)&0xFF), og=(int)((on>>8)&0xFF), ob=(int)(on&0xFF);
    return ((uint32_t)((zr*(15-a)+orr*a)/15) << 16)
         | ((uint32_t)((zg*(15-a)+og *a)/15) << 8)
         |  (uint32_t)((zb*(15-a)+ob *a)/15);
}

void simge_ciz(int x, int y, simge_id_t id, int boy) {
    const simge_t *s = simge_al(id);
    if (!s) return;
    const uint8_t *m = (boy <= 32) ? s->k32 : (boy <= 48 ? s->k48 : s->k64);
    int n = (boy <= 32) ? 32 : (boy <= 48 ? 48 : 64);
    for (int j = 0; j < n; j++)
        for (int i = 0; i < n; i++) {
            uint8_t v = m[j * n + i];
            int a = v & 0x0F;
            if (a == 0) continue;
            uint32_t renk = s->palet[(v >> 4) - 1];
            fb_put_pixel(x + i, y + j,
                         harman(fb_get_pixel(x + i, y + j), renk, a));
        }
}